words.value:
{
  key=$1
  gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
  if (key == "id") {
    value=$2
    gsub(/^[[:space:]"]+|[[:space:]"]+$/, "", value)
    print value
    exit
  }
}

